def load_world_polygons():
    """Return dict mapping uppercase country name to list of polygon rings [(lat, lon), ...]."""
    global _WORLD_POLYGONS_CACHE
    if _WORLD_POLYGONS_CACHE is not None:
        return _WORLD_POLYGONS_CACHE
    cache = {}
    try:
        raw = json.loads(zlib.decompress(base64.b64decode(_WORLD_177_B64)).decode("utf-8"))
        for k, rings in raw.items():
            cache[k.upper()] = [[(float(pt[0]), float(pt[1])) for pt in ring] for ring in rings]
    except Exception:
        pass
    for k, ring in BUILTIN_COUNTRY_POLYGONS.items():
        if k.upper() not in cache or not cache[k.upper()]:
            cache[k.upper()] = [ring]
    _WORLD_POLYGONS_CACHE = cache
    return cache


def lookup_gazetteer(name):
    key = str(name or "").strip().lower()
    if key in GAZETTEER:
        item = dict(GAZETTEER[key])
        item.setdefault("source", "WTB Strategic Gazetteer (Natural Earth)")
        return item
    for gk, gval in GAZETTEER.items():
        if gk in key or key in gk:
            item = dict(gval)
            item.setdefault("source", "WTB Strategic Gazetteer (Natural Earth)")
            return item
    return None
